            row_sum = 0
            for c in range(w):
                row_sum += test(r, c)
                p[r + 1][c + 1] = p[r][c + 1] + row_sum
        return p

    def rect(p, r1, c1, r2, c2):
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]

    colors = set(x for row in grid for x in row)
    best = None

    # Find the largest two-color rectangle whose border is entirely its base color.
    for base in colors:
        base_p = make_prefix(lambda r, c: grid[r][c] == base)
        for marker in colors:
            if marker == base:
                continue
            bad_p = make_prefix(lambda r, c: grid[r][c] not in (base, marker))
            for top in range(h):
                for bottom in range(top + 2, h):
                    height = bottom - top + 1
                    for left in range(w):
                        for right in range(left + 2, w):
                            area = height * (right - left + 1)
                            if area < 20 or (best is not None and area < best[0]):
                                continue
                            if rect(bad_p, top, left, bottom, right):
                                continue
                            width = right - left + 1
                            if rect(base_p, top, left, top, right) != width:
