from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    def prefix(predicate):
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            s = 0
            for c in range(w):
                s += predicate(r, c)
                p[r + 1][c + 1] = p[r][c + 1] + s
        return p

    def total(p, r1, c1, r2, c2):
        if r1 > r2 or c1 > c2:
            return 0
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]

    best = None
    for base in set(x for row in grid for x in row):
        if base == bg:
            continue
        invalid = prefix(lambda r, c: grid[r][c] not in (bg, base))
        bp = prefix(lambda r, c: grid[r][c] == base)

        for top in range(h - 2):
            for bottom in range(top + 2, h):
                height = bottom - top + 1
                for left in range(w - 2):
                    for right in range(left + 2, w):
                        width = right - left + 1
                        area = height * width
                        if area < 20 or (best and area <= best[0]):
                            continue
                        if total(invalid, top, left, bottom, right):
                            continue

                        perimeter = 2 * width + 2 * height - 4
                        border_base = total(bp, top, left, bottom, right)
                        if height > 2 and width > 2:
                            border_base -= total(bp, top + 1, left + 1,
                                                 bottom - 1, right - 1)
                        if border_base != perimeter:
                            continue

                        inner_base = total(bp, top + 1, left + 1,
                                            bottom - 1, right - 1)
                        inner_area = (height - 2) * (width - 2)
                        if inner_base == 0 or inner_base == inner_area:
                            continue
                        best = (area, top, left, bottom, right, base)

    if best is None:
        return grid

    _, top, left, bottom, right, base = best
    out = [row[left:right + 1] for row in grid[top:bottom + 1]]
    oh, ow = len(out), len(out[0])

