                        x, y = y, -x
                    transformed.append((x, y))
                mr = min(x for x, y in transformed)
                mc = min(y for x, y in transformed)
                forms.append(tuple(sorted((x - mr, y - mc)
                                          for x, y in transformed)))
        return min(forms)

    # Record shapes and colors of the small objects outside the framed panel.
    panel_cells = {(r, c) for r in range(top, bottom + 1)
                   for c in range(left, right + 1)}
    seen = set()
    shape_colors = Counter()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in panel_cells or color in (bg, base) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in panel_cells and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            shape = canonical([(x - r, y - c) for x, y in cells])
            shape_colors[(shape, color)] += 1

    # Replace each connected background-colored stencil piece by the color
    # of the most frequent matching object shape outside the panel.
    seen = set()
    for r in range(oh):
        for c in range(ow):
            if out[r][c] != bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < oh and 0 <= ny < ow and
                        out[nx][ny] == bg and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            shape = canonical([(x - r, y - c) for x, y in cells])
            votes = Counter()
            for (other_shape, color), count in shape_colors.items():
                if other_shape == shape:
                    votes[color] += count
            if votes:
                chosen = max(votes, key=lambda color: votes[color])
                for x, y in cells:
                    out[x][y] = chosen

    return out
